package com.acme.billing.gateway;

import io.github.resilience4j.retry.annotation.Retry;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class GatewayClientRetryTest {

    @Test
    void createChargeMustNotBeAutomaticallyRetried() throws Exception {
        // POST /v1/charges is not idempotent: a read timeout can mean the gateway
        // already captured the charge, so blind retries create duplicate charges.
        assertFalse(
            GatewayClient.class
                .getMethod("createCharge", ChargeRequest.class)
                .isAnnotationPresent(Retry.class),
            "createCharge must not carry @Retry unless it sends a deterministic Idempotency-Key");
    }

    @Test
    void getChargeRemainsRetryable() throws Exception {
        assertTrue(
            GatewayClient.class
                .getMethod("getCharge", String.class)
                .isAnnotationPresent(Retry.class),
            "GET charges are safe to retry");
    }
}
